import { describe, expect, it } from "vitest";

import { isSingleEmoji } from "./emojis.js";

describe("isSingleEmoji", () => {
	it.each([
		["simple emoji", "🔨"],
		["profession with skin tone", "👩🏽‍💻"],
		["family", "👨‍👩‍👧‍👦"],
		["country flag", "🇺🇸"],
		["keycap", "1️⃣"],
		["variation selector", "❤️"],
		["skin tone", "👍🏽"],
		["rainbow flag", "🏳️‍🌈"],
		["melting face", "🫠"],
		["phoenix", "🐦‍🔥"],
		["heart without variation selector", "❤"],
		["copyright", "©️"],
		["keycap without variation selector", "1\u20e3"],
		["hash keycap", "#️⃣"],
		["star keycap", "*️⃣"],
		["mixed skin tones", "🫱🏽‍🫲🏻"],
		["couple with skin tones", "👩🏽‍❤️‍💋‍👨🏻"],
		["hair component in sequence", "👩‍🦰"],
		["gendered activity", "🏃🏽‍♀️"],
		["directional sequence", "🚶🏽‍♀️‍➡️"],
		["England flag", "\u{1f3f4}\u{e0067}\u{e0062}\u{e0065}\u{e006e}\u{e0067}\u{e007f}"],
		["Emoji 17 orca", "\u{1facd}"],
		["Emoji 17 ballet dancer", "🧑🏽‍\u{1fa70}"],
	])("accepts %s", (_label, emoji) => {
		expect(isSingleEmoji(emoji)).toBe(true);
	});

	// Compatibility is intentional: these may render as multiple glyphs, but
	// rejecting unfamiliar combinations would also reject newly introduced emoji.
	it.each(["😀‍🔨", "🔨🏽", "🇦🇦"])("allows nonstandard emoji structure %s", (emoji) => {
		expect(isSingleEmoji(emoji)).toBe(true);
	});

	it.each([
		["undefined", undefined],
		["null", null],
		["number", 1],
		["object", {}],
		["empty string", ""],
		["plain text", "hello"],
		["text before emoji", "hello 🔨"],
		["text after emoji", "🔨 hello"],
		["adjacent emoji", "🔨🔨"],
		["emoji separated by a space", "🔨 🔨"],
		["leading space", " 🔨"],
		["trailing space", "🔨 "],
		["leading newline", "\n🔨"],
		["trailing newline", "🔨\n"],
		["trailing tab", "🔨\t"],
		["leading joiner", "\u200d🔨"],
		["trailing joiner", "🔨\u200d"],
		["unrelated combining mark", "🔨\u0301"],
		["unpaired high surrogate", "\ud800"],
		["unpaired low surrogate", "\udc00"],
		["bare digit", "1"],
		["bare hash", "#"],
		["bare star", "*"],
		["single regional indicator", "🇺"],
		["two flags", "🇺🇸🇬🇧"],
		["two keycaps", "1️⃣2️⃣"],
		["two compound emoji", "👩🏽‍💻👩🏽‍💻"],
		["text joined to emoji", "🔨\u200dA"],
		["duplicate joiner", "🔨\u200d\u200d🔨"],
		["duplicate skin tone", "👍🏽🏽"],
		["unterminated tag sequence", "\u{1f3f4}\u{e0067}"],
		["mathematical symbol", "∀"],
		["standalone skin tone", "🏽"],
		["standalone hair component", "🦰"],
		["overlong emoji string", "🔨".repeat(51)],
		["data URL", "data:image/svg+xml,🔨"],
		["HTTP URL", "https://example.com/🔨"],
		["image path", "/images/🔨"],
		["icon path", "/icons/🔨"],
		["Notion URL", "notion:🔨"],
		["attachment URL", "attachment:🔨"],
	])("rejects %s", (_label, emoji) => {
		expect(isSingleEmoji(emoji)).toBe(false);
	});
});
